solution.solution.cpp:
#include <string>
#include <vector>

struct Step { std::string name; std::string undo; bool succeeds; };
struct Result { bool ok; std::vector<std::string> calls; };

Result initialise(const std::vector<Step>& steps)
{
    Result r{ true, {} };
    std::vector<const Step*> done;
    for (const Step& s : steps)
    {
        r.calls.push_back(s.name);
        if (!s.succeeds)
        {
            r.ok = false;
            for (auto it{ done.rbegin() }; it != done.rend(); ++it) r.calls.push_back((*it)->undo);   // undo in reverse
            return r;
        }
        done.push_back(&s);
    }
    return r;
}

std::vector<std::string> unload(const std::vector<Step>& steps)
{
    std::vector<std::string> calls;
    for (auto it{ steps.rbegin() }; it != steps.rend(); ++it) calls.push_back(it->undo);
    return calls;
}

unitTests:
using C = std::vector<std::string>;
TEST("everything succeeds")
{
    const Result r{ initialise({ { "create device", "delete device", true }, { "create link", "delete link", true } }) };
    CHECK(r.ok);
    CHECK(r.calls == C({ "create device", "create link" }));
}
TEST("the example")
{
    const Result r{ initialise({ { "create device", "delete device", true }, { "create link", "delete link", false }, { "allocate state", "free state", true } }) };
    CHECK(!r.ok);
    CHECK(r.calls == C({ "create device", "create link", "delete device" }));
}
TEST("a later failure undoes everything before it, in reverse")
{
    const Result r{ initialise({ { "a", "undo a", true }, { "b", "undo b", true }, { "c", "undo c", true }, { "d", "undo d", false } }) };
    CHECK(r.calls == C({ "a", "b", "c", "d", "undo c", "undo b", "undo a" }));
}
TEST("the first step fails") { const Result r{ initialise({ { "a", "undo a", false }, { "b", "undo b", true } }) }; CHECK(r.calls == C({ "a" })); CHECK(!r.ok); }
TEST("unload is the reverse") { CHECK(unload({ { "a", "undo a", true }, { "b", "undo b", true }, { "c", "undo c", true } }) == C({ "undo c", "undo b", "undo a" })); }

